var consumeNumber=require("../../tokenizer/utils").consumeNumber,TYPE=require("../../tokenizer").TYPE,DIMENSION=TYPE.Dimension;module.exports={name:"Dimension",structure:{value:String,unit:String},parse:function(){var e=this.scanner.tokenStart,n=consumeNumber(this.scanner.source,e);return this.eat(DIMENSION),{type:"Dimension",loc:this.getLocation(e,this.scanner.tokenStart),value:this.scanner.source.substring(e,n),unit:this.scanner.source.substring(n,this.scanner.tokenStart)}},generate:function(e){this.chunk(e.value),this.chunk(e.unit)}};